INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-login', 0, 'lab', 'Форма входа', 'Соберите форму входа: она отправляется методом POST на адрес /login; внутри поле почты (type=email, name=email), поле пароля (type=password, name=password) и кнопка отправки. У каждого поля должна быть подпись.', '', 'У form два атрибута: action и method. Подпись — label с for, равным id поля; у кнопки type=submit.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-search', 1, 'lab', 'Форма поиска', 'Форма поиска отправляет запрос методом GET на /search. Поле — type=search с именем q; видимой подписи у него нет, поэтому назовите его для скринридера через aria-label. Форме задайте role="search", а кнопке — текст «Найти».', '', 'GET кладёт запрос в адрес: /search?q=…. Поле без видимого label получает имя через атрибут aria-label. Роль формы — атрибут role.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-email-required', 2, 'lab', 'Обязательная почта', 'Форма подписки: поле почты должно быть обязательным и иметь тип email, чтобы браузер сам проверил вид адреса. Добавьте подпись «Почта», имя поля — email.', '', 'required — булев атрибут, пишется без значения. Тип email включает встроенную проверку «что-то@что-то». Подпись — label for=id.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-password-new', 3, 'lab', 'Пароль при регистрации', 'Поле нового пароля: type=password, имя password, обязательное, не короче 8 символов (minlength). Менеджер паролей должен понять, что это новый пароль: autocomplete="new-password". Подпись у поля уже есть — не потеряйте её.', '', 'minlength="8" ограничивает длину снизу; при входе в существующий аккаунт было бы current-password, при регистрации — new-password.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-number', 4, 'lab', 'Количество товара', 'Поле «Количество» — число от 1 до 10 с шагом 1, по умолчанию 1. Имя поля qty, тип number, границы задайте атрибутами браузера, а не скриптом.', '', 'У number есть атрибуты min, max и step; значение по умолчанию задаёт value.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-radio-group', 5, 'lab', 'Радиогруппа', 'Выбор способа доставки: группа из двух радиокнопок («Почтой» со значением post и «Курьером» со значением courier) с общим именем delivery. Оберните группу в fieldset с заголовком legend «Доставка»; по умолчанию выбран курьер. У каждой кнопки есть подпись.', '', 'Радиокнопки с одним name образуют группу. fieldset собирает группу, legend — её вопрос (первый ребёнок fieldset). checked отмечает кнопку.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-consent', 6, 'lab', 'Согласие флажком', 'Флажок согласия с правилами: type=checkbox, имя agree, значение yes. Он обязателен, а подпись — «Согласен с правилами» — должна быть связана с флажком, чтобы клик по тексту его отмечал.', '', 'Самый короткий способ связать подпись — обернуть флажок тегом label. Обязательность — атрибут required.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-select-groups', 7, 'lab', 'Список с группами', 'Выпадающий список городов: select с именем city, внутри две группы optgroup (у каждой есть label), в группах вместе не меньше четырёх вариантов option. У каждого option задайте value. Подпись списка — «Город».', '', 'Структура: select → optgroup label="…" → option value="…". Подпись для select — тот же label for.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-textarea', 8, 'lab', 'Многострочное поле', 'Поле для сообщения: textarea с именем message, высотой в 5 строк, не длиннее 500 символов. Подпись — «Сообщение».', '', 'Размер textarea задают rows и cols, предел длины — maxlength.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-datalist', 9, 'lab', 'Подсказки в поле', 'Поле «Город» с подсказками: input с именем city связан списком datalist, у которого id="cities" и не меньше трёх option. Человек может выбрать из списка или ввести своё. У поля есть подпись.', '', 'Связь двух элементов — атрибут list у input, равный id списка. Варианты datalist — теги option с value.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-describedby', 10, 'lab', 'Подсказка к полю', 'У поля пароля есть подсказка «Не короче 8 символов». Дайте абзацу с подсказкой id="hint" и свяжите её с полем атрибутом aria-describedby, чтобы скринридер прочитал её после названия поля.', '', 'Значение aria-describedby — id элемента с пояснением (без решётки).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-button-types', 11, 'lab', 'Кнопки внутри формы', 'В форме две кнопки. «Показать пароль» нужна скрипту и не должна отправлять форму, «Войти» — отправляет. Задайте типы так, чтобы в форме не осталось кнопки без type.', '', 'У button три типа: submit (по умолчанию), button и reset. Кнопка без type внутри формы — отправляющая.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-file', 12, 'lab', 'Загрузка файлов', 'Форма загрузки фотографий: поле type=file с именем photo, принимающее только изображения (accept="image/*") и позволяющее выбрать несколько файлов (multiple). Подпись — «Фотографии».', '', 'accept ограничивает тип выбираемых файлов, multiple — булев атрибут без значения.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-hidden', 13, 'lab', 'Служебное поле', 'Форма правки записи: вместе с видимым полем «Заголовок» (имя title) на сервер должен уйти номер записи — скрытое поле с именем id и значением 42. Форма отправляется методом POST.', '', 'Скрытое поле — input type=hidden: его не видно, но имя и значение попадают в запрос. Подписи оно не требует.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-refactor', 14, 'lab', 'Исправьте форму заказа', 'Форма сделана на div: подписи — просто текст, а «кнопка» — div с onclick. Исправьте её: у каждого поля настоящий label, телефону — тип tel, вместо div с обработчиком — button с type=submit и текстом «Заказать». Атрибут onclick в форме не нужен.', '', 'Для подписей используйте label (for + id или обёртка). div[onclick] замените на button; тип tel даёт телефону цифровую клавиатуру.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-readonly-disabled', 15, 'lab', 'readonly и disabled', 'В форме оформления два поля. «Страна» (имя country, значение «Россия») должна быть видна и уходить на сервер, но пользователь её менять не может. «Промокод» (имя promo) выключено совсем: не получает фокус и на сервер не уходит. Подписи сохраните.', '', 'readonly оставляет поле в запросе, disabled — убирает. Оба атрибута булевы.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-error-message', 16, 'lab', 'Сообщение об ошибке', 'Поле почты не прошло проверку. Сообщение «Неверная почта» должно быть текстом с id="err" и ролью alert (озвучивается сразу), связано с полем через aria-describedby и отмечено у поля как aria-invalid="true". Подпись поля сохраните.', '', 'Три атрибута у input: aria-invalid="true", aria-describedby с id сообщения. У самого сообщения — role="alert".', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 15, 'w15-autocomplete', 17, 'lab', 'Форма адреса с автозаполнением', 'Форма доставки с тремя полями: «ФИО» (имя fullname, autocomplete="name"), «Почта» (имя email, тип email, autocomplete="email") и «Индекс» (имя zip, autocomplete="postal-code", inputmode="numeric"). Подписи уже есть.', '', 'autocomplete подсказывает браузеру, что подставить; inputmode="numeric" только меняет клавиатуру, тип остаётся текстовым.', '{}');
